Bash(node -e "
const {Client}=require\('pg'\);
const c=new Client\({connectionString:process.env.DATABASE_URL, ssl:{rejectUnauthorized:false}}\);
c.connect\(\).then\(async \(\)=>{
  // Staff can read all projects
  await c.query\(\\`
    CREATE POLICY \\"projects: staff read all\\"
    ON public.projects FOR SELECT
    USING \(
      EXISTS \(
        SELECT 1 FROM public.profiles p
        WHERE p.id = auth.uid\(\)
          AND p.role IN \('lexops_admin', 'lexops_member'\)
      \)
    \)
  \\`\);
  console.log\('Created: staff read all'\);

  // Clients can read assigned projects
  await c.query\(\\`
    CREATE POLICY \\"projects: client read own\\"
    ON public.projects FOR SELECT
    USING \(
      EXISTS \(
        SELECT 1 FROM public.project_members pm
        WHERE pm.project_id = \(projects.id\)::integer
          AND pm.user_id = auth.uid\(\)
      \)
    \)
  \\`\);
  console.log\('Created: client read own'\);

  // Admins can write \(insert/update/delete\)
  await c.query\(\\`
    CREATE POLICY \\"projects: admin write\\"
    ON public.projects FOR ALL
    USING \(
      EXISTS \(
        SELECT 1 FROM public.profiles p
        WHERE p.id = auth.uid\(\)
          AND p.role = 'lexops_admin'
      \)
    \)
  \\`\);
  console.log\('Created: admin write'\);

  // Verify
  const r = await c.query\(\\"SELECT policyname, cmd FROM pg_policies WHERE tablename='projects'\\"\);
  console.log\('All policies:', r.rows\);
  c.end\(\);
}\).catch\(e=>console.log\('Error:',e.message\)\);
" 2>&1)

